#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    vector<int> v;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        v.push_back(x);
    }

    transform(v.begin(), v.end(), v.begin(), [](int x) {
        return x * 2;
    });

    for (int x : v) {
        cout << x << endl;
    }
    return 0;
}
